<?php  namespace App\Modules\IdentityAccess\Controllers;  use App\Modules\IdentityAccess\Models\User; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Hash; use Illuminate\Support\Str; use Illuminate\Validation\Rule;  class UserController extends Controller {     private function resolveActor(Request $request): ?User     {         $actor = $request->user() ?? $request->attributes->get('auth_user');         return $actor instanceof User ? $actor : null;     }      private function canManageUsers(User $actor, ?string $branchId = null): bool     {         if ((bool) $actor->is_org_admin) {             return true;         }          if (method_exists($actor, 'hasPermissionInContext')) {             return $actor->hasPermissionInContext('users.manage', $branchId)                 || $actor->hasPermissionInContext('employees.manage', $branchId);         }          return false;     }      private function canViewUsers(User $actor, ?string $branchId = null): bool     {         if ($this->canManageUsers($actor, $branchId)) {             return true;         }          if (method_exists($actor, 'hasPermissionInContext')) {             return $actor->hasPermissionInContext('users.view', $branchId)                 || $actor->hasPermissionInContext('branches.view', $branchId);         }          return false;     }      public function index(Request $request): JsonResponse     {         $actor = $this->resolveActor($request);         if (! $actor) {             return response()->json(['message' => 'Unauthorized.'], 401);         }          $branchId = $request->query('branch_id');         $branchId = is_string($branchId) && $branchId !== '' ? $branchId : null;         if ($branchId !== null && ! Str::isUuid($branchId)) {             return response()->json(['message' => 'Invalid branch_id format.'], 422);         }          if (! $this->canViewUsers($actor, $branc