        ]);          $created = DB::transaction(function () use ($validated, $orgId, $actor): User {             $user = new User();             $user->id = (string) Str::uuid();             $user->organization_id = $orgId;             $user->employee_code = trim($validated['employee_code']);             $user->email = isset($validated['email']) && $validated['email'] !== '' ? strtolower(trim($validated['email'])) : null;             $user->full_name = trim($validated['full_name']);             $user->password_hash = Hash::make($validated['password']);             if (! empty($validated['pin'])) {                 $user->pin_hash = Hash::make((string) $validated['pin']);             }             $user->is_org_admin = (bool) ($validated['is_org_admin'] ?? false) && (bool) $actor->is_org_admin;             $user->status = strtoupper((string) ($validated['status'] ?? 'ACTIVE'));             $user->failed_login_attempts = 0;             $user->save();              if (! empty($validated['role_id'])) {                 DB::table('user_branch_roles')->insert([                     'id' => (string) Str::uuid(),                     'organization_id' => $orgId,                     'user_id' => $user->id,                     'branch_id' => $validated['branch_id'] ?? null,                     'role_id' => $validated['role_id'],                     'created_at' => now(),                 ]);             }              return $user;         });          return response()->json([             'message' => 'User created successfully.',             'data' => $created,         ], 201);     }      public function update(Request $request, string $id): JsonResponse     {         if (! Str::isUuid($id)) {             return response()->json(['message' => 'Invalid user ID format.'], 422);         }          $actor = $this->resolveActor($request);         if (! $actor) {             return response()->json(['message' => 'Unauthorized.'], 401);         }          if (! $this->canManageUsers($a